function countSubarrays(nums, k) {
  let total = 0;
  let ending = new Map();

  for (const num of nums) {
    const next = new Map([[num, 1]]);
    for (const [value, count] of ending) {
      const merged = value & num;
      next.set(merged, (next.get(merged) ?? 0) + count);
    }
    total += next.get(k) ?? 0;
    ending = next;
  }
  return total;
}

