function countSubarrays(nums, k) {
  // Fix each left end and AND the elements in one by one.
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let and = nums[i];
    for (let j = i; j < nums.length; j++) {
      if (j > i) and &= nums[j];
      if (and === k) total++;
    }
  }
  return total;
}

