function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const bits = large ? 29 : 4;
  const pick = chance => { let value = 0; for (let b = 0; b < bits; b++) if (rand() < chance) value |= 1 << b; return value; };
  const k = rand() < 0.15 ? 0 : pick(large ? 0.3 : 0.4);
  // Most values contain every bit of k plus a few extra bits; now and then one loses a bit, which cuts the runs.
  const nums = Array.from({ length: n }, () => {
    let value = k | pick(large ? 0.15 : 0.3);
    if (rand() < (large ? 0.04 : 0.25)) value &= ~(1 << Math.floor(rand() * bits));
    return value;
  });
  return [nums, k];
}
